import hmac
import hashlib
import base64
import json
import time
import os
import secrets

class TokenVerifier:
    """Secure token verification with constant-time comparison and replay protection."""

    def __init__(self, secret_key: bytes):
        self._secret = secret_key
        self._used_tokens = set()
        self._max_age = 3600

    def _compute_signature(self, payload: bytes) -> bytes:
        """Compute HMAC-SHA256 signature."""
        return hmac.new(self._secret, payload, hashlib.sha256).digest()

    def create_token(self, user_id: str, role: str) -> str:
        """Create a signed token with claims."""
        nonce = secrets.token_hex(16)
        claims = {
            "sub": user_id,
            "role": role,
            "iat": int(time.time()),
            "exp": int(time.time()) + self._max_age,
            "jti": nonce
        }
        payload = base64.urlsafe_b64encode(json.dumps(claims).encode())
        signature = self._compute_signature(payload)
        sig_encoded = base64.urlsafe_b64encode(signature)
        return payload.decode() + "." + sig_encoded.decode()

    def verify_token(self, token: str) -> dict:
        """Verify token signature and claims."""
        parts = token.split(".")
        if len(parts) != 2:
            raise ValueError("Invalid token format")

        payload_b64, sig_b64 = parts[0], parts[1]

        # Decode and verify signature
        try:
            presented_sig = base64.urlsafe_b64decode(sig_b64)
            expected_sig = self._compute_signature(payload_b64.encode())
        except Exception:
            raise ValueError("Invalid token encoding")

        # Direct constant-time comparison of actual signatures
        if not hmac.compare_digest(presented_sig, expected_sig):
            raise ValueError("Invalid signature")

        # Decode claims
        try:
            claims = json.loads(base64.urlsafe_b64decode(payload_b64))
        except Exception:
            raise ValueError("Invalid payload")

        # Verify expiration
        if claims.get("exp", 0) < time.time():
            raise ValueError("Token expired")

        # Replay protection
        jti = claims.get("jti", "")
        if jti in self._used_tokens:
            raise ValueError("Token already used")
        self._used_tokens.add(jti)

        return claims


class AuthorizationService:
    """Role-based access control with token verification."""

    def __init__(self):
        self._secret = os.urandom(32)
        self._verifier = TokenVerifier(self._secret)
        self._permissions = {
            "admin": {"read", "write", "delete", "admin"},
            "editor": {"read", "write"},
            "viewer": {"read"}
        }
        self._users = {}

    def register_user(self, user_id: str, password: str, role: str = "viewer"):
        """Register user with password hash."""
        salt = os.urandom(16)
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        self._users[user_id] = {
            "password_hash": pw_hash,
            "salt": salt,
            "role": role
        }

    def authenticate(self, user_id: str, password: str) -> str:
        """Authenticate user and return token."""
        user = self._users.get(user_id)
        if not user:
            # Constant-time-ish: still do work
            hashlib.pbkdf2_hmac('sha256', password.encode(), os.urandom(16), 100000)
            raise ValueError("Authentication failed")

        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), user["salt"], 100000)
        if not hmac.compare_digest(pw_hash, user["password_hash"]):
            raise ValueError("Authentication failed")

        return self._verifier.create_token(user_id, user["role"])

    def authorize(self, token: str, required_permission: str) -> bool:
        """Check if token grants the required permission."""
        claims = self._verifier.verify_token(token)
        role = claims.get("role", "")
        permissions = self._permissions.get(role, set())
        return required_permission in permissions

    def get_user_info(self, token: str) -> dict:
        """Get user info from token - for display purposes."""
        claims = self._verifier.verify_token(token)
        return {"user_id": claims["sub"], "role": claims["role"]}


def main():
    service = AuthorizationService()
    service.register_user("alice", "secureP@ss123", "editor")
    service.register_user("bob", "b0bP@ssw0rd!", "viewer")

    # Normal authentication flow
    token = service.authenticate("alice", "secureP@ss123")
    print(f"Alice can write: {service.authorize(token, 'write')}")
    print(f"Alice can delete: {service.authorize(token, 'delete')}")


if __name__ == "__main__":
    main()
